import path from 'path'
import { fileURLToPath } from 'url'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'

import { initPayloadInt } from '../__helpers/shared/initPayloadInt.js'
import { tabSlug } from './collections/Tab/index.js'
import { defaultLocale, spanishLocale } from './shared.js'

let payload: Payload

const filename = fileURLToPath(import.meta.url)
const dirname = path.dirname(filename)

describe('Repro group in localized tab', () => {
  beforeAll(async () => {
    ;({ payload } = await initPayloadInt(dirname))
  })

  afterAll(async () => {
    await payload.destroy()
  })

  it('isolates locales for group inside localized tab', async () => {
    const doc = await payload.create({
      collection: tabSlug,
      locale: defaultLocale,
      data: {
        tabLocalized: {
          title: 'en title',
          group: { heading: 'english heading' },
        },
      },
    })

    await payload.update({
      collection: tabSlug,
      id: doc.id,
      locale: spanishLocale,
      data: {
        tabLocalized: {
          title: 'es title',
          group: { heading: 'spanish heading' },
        },
      },
    })

    const en = await payload.findByID({ collection: tabSlug, id: doc.id, locale: defaultLocale })
    const es = await payload.findByID({ collection: tabSlug, id: doc.id, locale: spanishLocale })

    console.log('EN', JSON.stringify(en.tabLocalized))
    console.log('ES', JSON.stringify(es.tabLocalized))

    expect(en.tabLocalized?.group?.heading).toBe('english heading')
    expect(es.tabLocalized?.group?.heading).toBe('spanish heading')
  })
})
